changeSet.sql:
GRANT SELECT, INSERT, UPDATE, DELETE ON ALL TABLES IN SCHEMA public TO saigt_app;
GRANT USAGE, SELECT ON ALL SEQUENCES IN SCHEMA public TO saigt_app;
ALTER DEFAULT PRIVILEGES IN SCHEMA public GRANT SELECT, INSERT, UPDATE, DELETE ON TABLES TO saigt_app;
ALTER DEFAULT PRIVILEGES IN SCHEMA public GRANT USAGE, SELECT ON SEQUENCES TO saigt_app;
REVOKE UPDATE, DELETE ON auditoria FROM saigt_app;
